<template>
  <div slot="header">
    <div id="TagsRelation" :style="{width: '100%', height: '1000px'}"></div>
    <div class="title font-weight-midle mb-2 text-xs-center black--text">说明</div>
    <div class="font-weight-thin text-xs-center grey--text" >
      <span class="font-weight-bold">点</span>：标签，点越大，该标签出现次数越多；<br>
      <span class="font-weight-bold">线</span>：关系，线越粗，两个标签之间的关系越密切；<br>
      <span class="font-weight-bold">关系</span>：当一些标签，出现在同一个职位中时，认为它们之间有一定的关系；<br>
      <span class="font-weight-bold">注</span>：只保留出现次数大于2次的标签；<br>
      <span class="font-weight-bold">使用提示</span>：左键可拖拽，滚轮可缩放，指向高亮周边。
    </div>
  </div>
</template>

<script>
const axios = require('axios');
export default {
  data: () => ({
    data_tag_links: './data/tag_links.json',
    data_tag_nodes: './data/tag_nodes.json',
  }),
  mounted() {
    this.drawGraph();
  },
  methods: {
    drawGraph(){
        // 基于准备好的dom，初始化echarts实例
        let myChart = this.$echarts.init(document.getElementById('TagsRelation'));

        axios.get('./data/tag_nodes.json?v=6').then((response) => {
          let data_tag_nodes = response.data;
          axios.get('./data/tag_links.json?v=6').then((response) => {
            let data_tag_links = response.data;

            let option = {
                title: {
                    text: '标签关系',
                    subtext: '标签关系',
                    top: 'top',
                    left: 'center'
                },
                tooltip: {},
                animation: false,
                series : [
                    {
                        name: '标签关系',
                        type: 'graph',
                        layout: 'force',
                        data: data_tag_nodes,
                        links: data_tag_links,
                        categories: 0,
                        roam: true,
                        itemStyle: {
                          color: '#2f4554'
                        },
                        label: {
                            normal: {
                                position: 'right'
                            }
                        },
                        force: {
                            repulsion: 100
                        },
                        focusNodeAdjacency: true,
                    }
                ]
            };
            // 绘制图表
            myChart.setOption(option);

          });
        });
    },
  }
}
</script>
